import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.yMGLHqpH.js";const k=JSON.parse('{"title":"服務與憑證","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/maintenance.md","filePath":"zh-TW/guide/maintenance.md"}'),n={name:"zh-TW/guide/maintenance.md"};function h(l,s,d,p,c,o){return i(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="服務與憑證" tabindex="-1">服務與憑證 <a class="header-anchor" href="#服務與憑證" aria-label="標題連結： &quot;服務與憑證&quot;">​</a></h1><h2 id="自訂-systemd-服務" tabindex="-1">自訂 systemd 服務 <a class="header-anchor" href="#自訂-systemd-服務" aria-label="標題連結： &quot;自訂 systemd 服務&quot;">​</a></h2><p>編輯 systemd 服務檔案，以 <code>daed</code> 為例：</p><div class="language-sh vp-adaptive-theme"><button title="複製程式碼" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daed.service</span></span></code></pre></div><p>新檔案儲存於 <code>/etc/systemd/system/daed.service</code>，原始檔案仍位於 <code>/lib/systemd/system/daed.service</code>。更新套件時不會覆寫新檔案。</p><h2 id="允許非-root-使用者讀取-let-s-encrypt-憑證" tabindex="-1">允許非 root 使用者讀取 Let’s Encrypt 憑證 <a class="header-anchor" href="#允許非-root-使用者讀取-let-s-encrypt-憑證" aria-label="標題連結： &quot;允許非 root 使用者讀取 Let’s Encrypt 憑證&quot;">​</a></h2><p>v2ray、xray、juicity 和 juicity-rs 服務以 <code>nobody</code> 使用者身分執行。因為該使用者預設無法讀取 <code>/etc/letsencrypt/live</code> 中的憑證，所以需要透過 ACL 授予讀取權限。</p><h3 id="安裝-acl-套件" tabindex="-1">安裝 <code>acl</code> 套件 <a class="header-anchor" href="#安裝-acl-套件" aria-label="標題連結： &quot;安裝 `acl` 套件&quot;">​</a></h3><p>以下以 Debian、Ubuntu 為例：</p><div class="language-sh vp-adaptive-theme"><button title="複製程式碼" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acl</span></span></code></pre></div><h3 id="授予-nobody-憑證讀取權限" tabindex="-1">授予 <code>nobody</code> 憑證讀取權限 <a class="header-anchor" href="#授予-nobody-憑證讀取權限" aria-label="標題連結： &quot;授予 `nobody` 憑證讀取權限&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="複製程式碼" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setfacl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u:nobody:rX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/letsencrypt/{live,archive}</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setfacl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> u:nobody:rX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/letsencrypt</span></span></code></pre></div><h3 id="在憑證續期後自動設定-acl" tabindex="-1">在憑證續期後自動設定 ACL <a class="header-anchor" href="#在憑證續期後自動設定-acl" aria-label="標題連結： &quot;在憑證續期後自動設定 ACL&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="複製程式碼" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certbot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> renew</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deploy-hook</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;setfacl -R -m u:nobody:rX /etc/letsencrypt/{live,archive}&quot;</span></span></code></pre></div>',14)])])}const F=a(n,[["render",h]]);export{k as __pageData,F as default};
